// Pass the esp-truma value to the virtual Victron device.
// The esp-truma only reports on changes, often nothing for a long time at night.
// If values stay away for 2 h (ESP off, sensor gone), the trigger sends
// "timeout" and the device is reported offline instead of showing stale values.
const online = context.get('online') || false;

if (msg.payload === 'timeout') {
    if (!online) return null;
    context.set('online', false);
    node.status({ fill: 'grey', shape: 'ring', text: 'offline' });
    return { connected: false };
}

let v = parseFloat(msg.payload);
if (isNaN(v)) return null;   // "nan" when the sensor value is missing

let path = 'Temperature';
if (msg.topic.endsWith('humidity/state')) path = 'Humidity';
if (msg.topic.endsWith('level/state')) {
    path = 'Level';
    v = Math.min(100, Math.max(0, v));
}

const out = [];
if (!online) {
    context.set('online', true);
    out.push({ connected: true });
}
out.push({ payload: { [path]: Math.round(v * 10) / 10 } });
node.status({ fill: 'green', shape: 'dot', text: path + ' ' + v });
return [out];

